-- Mako Production System (Mako Gold Mine, Petowal Mining Company S.A.) schema for SQLite
-- Generated by mps/build_ddl.py from mps/schema/mps_schema.json version 0.1.0. Do not edit; regenerate.
-- Safe to re-run on an existing database: tables use IF NOT EXISTS, views are dropped and recreated,
-- seeds are inserted only when missing. Structural changes to existing tables need a migration.
-- Run: sqlite3 mps.db < schema_sqlite.sql  (SQLite 3.31 or later; every connection must set PRAGMA foreign_keys = ON)
--
-- Naming: Excel table -> SQL table (primary key)
--   tblPlant           sheet Plant              -> plant_daily (date)
--   tblMovement        sheet Mining_Movements   -> movement (id)
--   tblMiningDaily     sheet Mining_Daily       -> mining_daily (date)
--   tblFleet           sheet Fleet              -> fleet (id)
--   tblSafety          sheet Safety             -> safety_daily (date)
--   tblSafetyHistory   sheet Config             -> safety_history (month)
--   tblGold            sheet Gold               -> gold (id)
--   tblBudget          sheet Budget             -> budget (month)
--   tblCommentary      sheet Commentary         -> commentary (id)
--   tblSources         sheet Lists              -> sources (source)
--   tblDestinations    sheet Lists              -> destinations (destination)
--   tblStockpiles      sheet Config             -> stockpiles (stockpile)
--   lists           -> ref_<list>(code, sort_order), one row per drop-down value
-- Columns are the Excel field names in lower case. Units: tonnes dry metric, grades g/t,
-- gold troy ounces (31.1035 g), percentages stored as fractions 0 to 1.
-- Types: date DATE, text TEXT, list TEXT + FOREIGN KEY, number NUMERIC(18,4), int INTEGER, pct NUMERIC(9,6) CHECK 0..1.
-- CHECK constraints come from the schema min/max; NULL means not reported and always passes.
-- Calculated fields are GENERATED ALWAYS AS ... VIRTUAL with numeric operands cast to REAL
-- (SQLite stores integral NUMERIC values as INTEGER and would otherwise divide as integers);
-- fields SQLite cannot generate and Excel lookups live in the <table>_calc views.
-- kpi_daily reproduces the workbook Calc_Daily day columns; kpi_monthly gives the month totals
-- with ratios recomputed from summed numerators and denominators.
-- Excel-only helper fields not carried to SQL: tblCommentary.Seq_Day, tblCommentary.Key_Day.

PRAGMA foreign_keys = ON;

-- ---------------------------------------------------------------- reference lists (drop-down values)
CREATE TABLE IF NOT EXISTS ref_shift (
    code TEXT PRIMARY KEY,
    sort_order INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS ref_material (
    code TEXT PRIMARY KEY,
    sort_order INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS ref_area (
    code TEXT PRIMARY KEY,
    sort_order INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS ref_equipment_class (
    code TEXT PRIMARY KEY,
    sort_order INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS ref_gold_movement_type (
    code TEXT PRIMARY KEY,
    sort_order INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS ref_yes_no (
    code TEXT PRIMARY KEY,
    sort_order INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS ref_source_type (
    code TEXT PRIMARY KEY,
    sort_order INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS ref_destination_type (
    code TEXT PRIMARY KEY,
    sort_order INTEGER NOT NULL
);

-- ---------------------------------------------------------------- reference tables (Lists and Config sheets)
CREATE TABLE IF NOT EXISTS sources (
    source TEXT NOT NULL,
    type TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT pk_sources PRIMARY KEY (source),
    CONSTRAINT fk_sources_type FOREIGN KEY (type) REFERENCES ref_source_type (code)
);
CREATE TABLE IF NOT EXISTS destinations (
    destination TEXT NOT NULL,
    type TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT pk_destinations PRIMARY KEY (destination),
    CONSTRAINT fk_destinations_type FOREIGN KEY (type) REFERENCES ref_destination_type (code)
);
CREATE TABLE IF NOT EXISTS stockpiles (
    stockpile TEXT NOT NULL,
    opening_t NUMERIC(18,4),
    opening_gpt NUMERIC(18,4),
    plant_feed TEXT,
    survey_date DATE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT pk_stockpiles PRIMARY KEY (stockpile),
    CONSTRAINT fk_stockpiles_plant_feed FOREIGN KEY (plant_feed) REFERENCES ref_yes_no (code),
    CONSTRAINT fk_stockpiles_sources FOREIGN KEY (stockpile) REFERENCES sources (source),
    CONSTRAINT fk_stockpiles_destinations FOREIGN KEY (stockpile) REFERENCES destinations (destination)
);

-- ---------------------------------------------------------------- input tables
-- Processing plant, one row per day (owner: Processing (met accountant / shift supervisor))
CREATE TABLE IF NOT EXISTS plant_daily (
    date DATE NOT NULL,
    crushed_t NUMERIC(18,4),
    milled_t NUMERIC(18,4),
    head_grade_gpt NUMERIC(18,4),
    tails_grade_gpt NUMERIC(18,4),
    gravity_gold_oz NUMERIC(18,4),
    gold_poured_oz NUMERIC(18,4),
    mill_run_h NUMERIC(18,4),
    mill_planned_maint_h NUMERIC(18,4),
    mill_unplanned_down_h NUMERIC(18,4),
    crusher_run_h NUMERIC(18,4),
    cyanide_kg NUMERIC(18,4),
    lime_kg NUMERIC(18,4),
    grinding_media_kg NUMERIC(18,4),
    power_kwh NUMERIC(18,4),
    raw_water_m3 NUMERIC(18,4),
    gic_oz NUMERIC(18,4),
    comments TEXT,
    feed_oz NUMERIC(18,4) GENERATED ALWAYS AS (CAST(milled_t AS REAL) * CAST(head_grade_gpt AS REAL) / 31.1035) VIRTUAL,
    tails_oz NUMERIC(18,4) GENERATED ALWAYS AS (CAST(milled_t AS REAL) * CAST(tails_grade_gpt AS REAL) / 31.1035) VIRTUAL,
    recovered_oz NUMERIC(18,4) GENERATED ALWAYS AS (CAST(milled_t AS REAL) * (CAST(head_grade_gpt AS REAL) - CAST(tails_grade_gpt AS REAL)) / 31.1035) VIRTUAL,
    recovery_pct NUMERIC(9,6) GENERATED ALWAYS AS (CASE WHEN CAST(head_grade_gpt AS REAL) > 0 THEN 1 - CAST(tails_grade_gpt AS REAL) / CAST(head_grade_gpt AS REAL) END) VIRTUAL,
    throughput_tph NUMERIC(18,4) GENERATED ALWAYS AS (CASE WHEN CAST(mill_run_h AS REAL) > 0 THEN CAST(milled_t AS REAL) / CAST(mill_run_h AS REAL) END) VIRTUAL,
    availability_pct NUMERIC(9,6) GENERATED ALWAYS AS ((24 - CAST(mill_planned_maint_h AS REAL) - CAST(mill_unplanned_down_h AS REAL)) / 24.0) VIRTUAL,
    utilisation_pct NUMERIC(9,6) GENERATED ALWAYS AS (CASE WHEN (24 - CAST(mill_planned_maint_h AS REAL) - CAST(mill_unplanned_down_h AS REAL)) > 0 THEN CAST(mill_run_h AS REAL) / (24 - CAST(mill_planned_maint_h AS REAL) - CAST(mill_unplanned_down_h AS REAL)) END) VIRTUAL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT pk_plant_daily PRIMARY KEY (date),
    CONSTRAINT ck_plant_daily_crushed_t CHECK (crushed_t BETWEEN 0 AND 50000),
    CONSTRAINT ck_plant_daily_milled_t CHECK (milled_t BETWEEN 0 AND 50000),
    CONSTRAINT ck_plant_daily_head_grade_gpt CHECK (head_grade_gpt BETWEEN 0 AND 50),
    CONSTRAINT ck_plant_daily_tails_grade_gpt CHECK (tails_grade_gpt BETWEEN 0 AND 10),
    CONSTRAINT ck_plant_daily_gravity_gold_oz CHECK (gravity_gold_oz BETWEEN 0 AND 5000),
    CONSTRAINT ck_plant_daily_gold_poured_oz CHECK (gold_poured_oz BETWEEN 0 AND 20000),
    CONSTRAINT ck_plant_daily_mill_run_h CHECK (mill_run_h BETWEEN 0 AND 24),
    CONSTRAINT ck_plant_daily_mill_planned_maint_h CHECK (mill_planned_maint_h BETWEEN 0 AND 24),
    CONSTRAINT ck_plant_daily_mill_unplanned_down_h CHECK (mill_unplanned_down_h BETWEEN 0 AND 24),
    CONSTRAINT ck_plant_daily_crusher_run_h CHECK (crusher_run_h BETWEEN 0 AND 24),
    CONSTRAINT ck_plant_daily_cyanide_kg CHECK (cyanide_kg BETWEEN 0 AND 50000),
    CONSTRAINT ck_plant_daily_lime_kg CHECK (lime_kg BETWEEN 0 AND 100000),
    CONSTRAINT ck_plant_daily_grinding_media_kg CHECK (grinding_media_kg BETWEEN 0 AND 50000),
    CONSTRAINT ck_plant_daily_power_kwh CHECK (power_kwh BETWEEN 0 AND 1000000),
    CONSTRAINT ck_plant_daily_raw_water_m3 CHECK (raw_water_m3 BETWEEN 0 AND 100000),
    CONSTRAINT ck_plant_daily_gic_oz CHECK (gic_oz BETWEEN 0 AND 50000)
);

-- Material movements, one row per source, material and destination per day (or per shift) (owner: Mining (dispatch / production engineer))
CREATE TABLE IF NOT EXISTS movement (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date DATE NOT NULL,
    shift TEXT,
    source TEXT NOT NULL,
    material TEXT NOT NULL,
    destination TEXT NOT NULL,
    tonnes_t NUMERIC(18,4) NOT NULL,
    grade_gpt NUMERIC(18,4),
    bcm NUMERIC(18,4),
    loads INTEGER,
    comments TEXT,
    is_ore INTEGER GENERATED ALWAYS AS (CASE WHEN material LIKE 'Ore%' THEN 1 ELSE 0 END) VIRTUAL,
    contained_oz NUMERIC(18,4) GENERATED ALWAYS AS (CAST(tonnes_t AS REAL) * COALESCE(CAST(grade_gpt AS REAL), 0) / 31.1035) VIRTUAL,
    ore_oz NUMERIC(18,4) GENERATED ALWAYS AS (CASE WHEN material LIKE 'Ore%' THEN CAST(tonnes_t AS REAL) * COALESCE(CAST(grade_gpt AS REAL), 0) / 31.1035 ELSE 0 END) VIRTUAL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT fk_movement_shift FOREIGN KEY (shift) REFERENCES ref_shift (code),
    CONSTRAINT fk_movement_source FOREIGN KEY (source) REFERENCES sources (source),
    CONSTRAINT fk_movement_material FOREIGN KEY (material) REFERENCES ref_material (code),
    CONSTRAINT fk_movement_destination FOREIGN KEY (destination) REFERENCES destinations (destination),
    CONSTRAINT ck_movement_tonnes_t CHECK (tonnes_t BETWEEN 0 AND 200000),
    CONSTRAINT ck_movement_grade_gpt CHECK (grade_gpt BETWEEN 0 AND 100),
    CONSTRAINT ck_movement_bcm CHECK (bcm BETWEEN 0 AND 100000),
    CONSTRAINT ck_movement_loads CHECK (loads BETWEEN 0 AND 5000)
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_movement_key ON movement (date, COALESCE(shift, ''), source, material, destination);

-- Mining daily totals, one row per day (owner: Mining (production engineer))
CREATE TABLE IF NOT EXISTS mining_daily (
    date DATE NOT NULL,
    drill_m NUMERIC(18,4),
    blast_t NUMERIC(18,4),
    explosives_kg NUMERIC(18,4),
    diesel_l NUMERIC(18,4),
    dewatering_m3 NUMERIC(18,4),
    comments TEXT,
    powder_factor_kgpt NUMERIC(18,4) GENERATED ALWAYS AS (CASE WHEN CAST(blast_t AS REAL) > 0 THEN CAST(explosives_kg AS REAL) / CAST(blast_t AS REAL) END) VIRTUAL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT pk_mining_daily PRIMARY KEY (date),
    CONSTRAINT ck_mining_daily_drill_m CHECK (drill_m BETWEEN 0 AND 20000),
    CONSTRAINT ck_mining_daily_blast_t CHECK (blast_t BETWEEN 0 AND 500000),
    CONSTRAINT ck_mining_daily_explosives_kg CHECK (explosives_kg BETWEEN 0 AND 200000),
    CONSTRAINT ck_mining_daily_diesel_l CHECK (diesel_l BETWEEN 0 AND 200000),
    CONSTRAINT ck_mining_daily_dewatering_m3 CHECK (dewatering_m3 BETWEEN 0 AND 500000)
);

-- Mining fleet time model, one row per equipment class per day (owner: Mining (dispatch / maintenance planner))
CREATE TABLE IF NOT EXISTS fleet (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date DATE NOT NULL,
    equipment_class TEXT NOT NULL,
    units INTEGER NOT NULL,
    down_h NUMERIC(18,4),
    operating_h NUMERIC(18,4),
    comments TEXT,
    calendar_h NUMERIC(18,4) GENERATED ALWAYS AS (units * 24) VIRTUAL,
    available_h NUMERIC(18,4) GENERATED ALWAYS AS (units * 24 - CAST(down_h AS REAL)) VIRTUAL,
    availability_pct NUMERIC(9,6) GENERATED ALWAYS AS (CASE WHEN units > 0 THEN (units * 24 - CAST(down_h AS REAL)) / (units * 24.0) END) VIRTUAL,
    utilisation_pct NUMERIC(9,6) GENERATED ALWAYS AS (CASE WHEN (units * 24 - CAST(down_h AS REAL)) > 0 THEN CAST(operating_h AS REAL) / (units * 24 - CAST(down_h AS REAL)) END) VIRTUAL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT fk_fleet_equipment_class FOREIGN KEY (equipment_class) REFERENCES ref_equipment_class (code),
    CONSTRAINT ck_fleet_units CHECK (units BETWEEN 0 AND 200),
    CONSTRAINT ck_fleet_down_h CHECK (down_h BETWEEN 0 AND 4800),
    CONSTRAINT ck_fleet_operating_h CHECK (operating_h BETWEEN 0 AND 4800),
    CONSTRAINT uq_fleet_key UNIQUE (date, equipment_class)
);

-- Safety, health, environment and community, one row per day (owner: HSE)
CREATE TABLE IF NOT EXISTS safety_daily (
    date DATE NOT NULL,
    hours_employees NUMERIC(18,4),
    hours_contractors NUMERIC(18,4),
    fatality INTEGER,
    lti INTEGER,
    rwi INTEGER,
    mti INTEGER,
    fai INTEGER,
    near_miss INTEGER,
    hazard_reports INTEGER,
    hpi INTEGER,
    env_incidents INTEGER,
    community_incidents INTEGER,
    vehicle_incidents INTEGER,
    toolbox_talks INTEGER,
    inspections INTEGER,
    comments TEXT,
    hours_total NUMERIC(18,4) GENERATED ALWAYS AS (COALESCE(CAST(hours_employees AS REAL), 0) + COALESCE(CAST(hours_contractors AS REAL), 0)) VIRTUAL,
    recordables INTEGER GENERATED ALWAYS AS (COALESCE(fatality,0) + COALESCE(lti,0) + COALESCE(rwi,0) + COALESCE(mti,0)) VIRTUAL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT pk_safety_daily PRIMARY KEY (date),
    CONSTRAINT ck_safety_daily_hours_employees CHECK (hours_employees BETWEEN 0 AND 50000),
    CONSTRAINT ck_safety_daily_hours_contractors CHECK (hours_contractors BETWEEN 0 AND 50000),
    CONSTRAINT ck_safety_daily_fatality CHECK (fatality BETWEEN 0 AND 50),
    CONSTRAINT ck_safety_daily_lti CHECK (lti BETWEEN 0 AND 50),
    CONSTRAINT ck_safety_daily_rwi CHECK (rwi BETWEEN 0 AND 50),
    CONSTRAINT ck_safety_daily_mti CHECK (mti BETWEEN 0 AND 50),
    CONSTRAINT ck_safety_daily_fai CHECK (fai BETWEEN 0 AND 50),
    CONSTRAINT ck_safety_daily_near_miss CHECK (near_miss BETWEEN 0 AND 500),
    CONSTRAINT ck_safety_daily_hazard_reports CHECK (hazard_reports BETWEEN 0 AND 5000),
    CONSTRAINT ck_safety_daily_hpi CHECK (hpi BETWEEN 0 AND 50),
    CONSTRAINT ck_safety_daily_env_incidents CHECK (env_incidents BETWEEN 0 AND 50),
    CONSTRAINT ck_safety_daily_community_incidents CHECK (community_incidents BETWEEN 0 AND 50),
    CONSTRAINT ck_safety_daily_vehicle_incidents CHECK (vehicle_incidents BETWEEN 0 AND 50),
    CONSTRAINT ck_safety_daily_toolbox_talks CHECK (toolbox_talks BETWEEN 0 AND 500),
    CONSTRAINT ck_safety_daily_inspections CHECK (inspections BETWEEN 0 AND 500)
);

-- Prior-year safety history by month, for rolling 12-month rates (owner: HSE)
CREATE TABLE IF NOT EXISTS safety_history (
    month DATE NOT NULL,
    hours_total NUMERIC(18,4),
    recordables INTEGER,
    lti INTEGER,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT pk_safety_history PRIMARY KEY (month),
    CONSTRAINT ck_safety_history_month_first_of_month CHECK (strftime('%d', month) = '01'),
    CONSTRAINT ck_safety_history_hours_total CHECK (hours_total BETWEEN 0 AND 2000000),
    CONSTRAINT ck_safety_history_recordables CHECK (recordables BETWEEN 0 AND 100),
    CONSTRAINT ck_safety_history_lti CHECK (lti BETWEEN 0 AND 100)
);

-- Gold shipments and sales (owner: Finance / gold room)
CREATE TABLE IF NOT EXISTS gold (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date DATE NOT NULL,
    type TEXT NOT NULL,
    dore_kg NUMERIC(18,4),
    gold_oz NUMERIC(18,4) NOT NULL,
    silver_oz NUMERIC(18,4),
    reference TEXT,
    comments TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT fk_gold_type FOREIGN KEY (type) REFERENCES ref_gold_movement_type (code),
    CONSTRAINT ck_gold_dore_kg CHECK (dore_kg BETWEEN 0 AND 5000),
    CONSTRAINT ck_gold_gold_oz CHECK (gold_oz BETWEEN 0 AND 100000),
    CONSTRAINT ck_gold_silver_oz CHECK (silver_oz BETWEEN 0 AND 100000)
);
CREATE INDEX IF NOT EXISTS ix_gold_date ON gold (date);

-- Monthly budget (or latest forecast), one row per month (owner: Technical services / finance)
CREATE TABLE IF NOT EXISTS budget (
    month DATE NOT NULL,
    ore_mined_t NUMERIC(18,4),
    ore_grade_gpt NUMERIC(18,4),
    waste_t NUMERIC(18,4),
    milled_t NUMERIC(18,4),
    head_grade_gpt NUMERIC(18,4),
    recovery_pct NUMERIC(9,6),
    gold_poured_oz NUMERIC(18,4),
    hours_worked NUMERIC(18,4),
    drill_m NUMERIC(18,4),
    diesel_l NUMERIC(18,4),
    days INTEGER GENERATED ALWAYS AS (CAST(strftime('%d', date(month, 'start of month', '+1 month', '-1 day')) AS INTEGER)) VIRTUAL,
    ore_oz NUMERIC(18,4) GENERATED ALWAYS AS (COALESCE(CAST(ore_mined_t AS REAL),0) * COALESCE(CAST(ore_grade_gpt AS REAL),0) / 31.1035) VIRTUAL,
    tmm_t NUMERIC(18,4) GENERATED ALWAYS AS (COALESCE(CAST(ore_mined_t AS REAL),0) + COALESCE(CAST(waste_t AS REAL),0)) VIRTUAL,
    feed_oz NUMERIC(18,4) GENERATED ALWAYS AS (COALESCE(CAST(milled_t AS REAL),0) * COALESCE(CAST(head_grade_gpt AS REAL),0) / 31.1035) VIRTUAL,
    recovered_oz NUMERIC(18,4) GENERATED ALWAYS AS (COALESCE(CAST(milled_t AS REAL),0) * COALESCE(CAST(head_grade_gpt AS REAL),0) / 31.1035 * COALESCE(CAST(recovery_pct AS REAL),0)) VIRTUAL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT pk_budget PRIMARY KEY (month),
    CONSTRAINT ck_budget_month_first_of_month CHECK (strftime('%d', month) = '01'),
    CONSTRAINT ck_budget_ore_mined_t CHECK (ore_mined_t BETWEEN 0 AND 5000000),
    CONSTRAINT ck_budget_ore_grade_gpt CHECK (ore_grade_gpt BETWEEN 0 AND 50),
    CONSTRAINT ck_budget_waste_t CHECK (waste_t BETWEEN 0 AND 20000000),
    CONSTRAINT ck_budget_milled_t CHECK (milled_t BETWEEN 0 AND 5000000),
    CONSTRAINT ck_budget_head_grade_gpt CHECK (head_grade_gpt BETWEEN 0 AND 50),
    CONSTRAINT ck_budget_recovery_pct CHECK (recovery_pct BETWEEN 0 AND 1),
    CONSTRAINT ck_budget_gold_poured_oz CHECK (gold_poured_oz BETWEEN 0 AND 500000),
    CONSTRAINT ck_budget_hours_worked CHECK (hours_worked BETWEEN 0 AND 2000000),
    CONSTRAINT ck_budget_drill_m CHECK (drill_m BETWEEN 0 AND 500000),
    CONSTRAINT ck_budget_diesel_l CHECK (diesel_l BETWEEN 0 AND 10000000)
);

-- Daily report narrative, one row per comment (owner: All departments; compiled by the production engineer)
CREATE TABLE IF NOT EXISTS commentary (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    date DATE NOT NULL,
    area TEXT NOT NULL,
    comment TEXT NOT NULL,
    author TEXT,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT,
    CONSTRAINT fk_commentary_area FOREIGN KEY (area) REFERENCES ref_area (code)
);
CREATE INDEX IF NOT EXISTS ix_commentary_date ON commentary (date);

-- ---------------------------------------------------------------- audit: keep updated_at current
CREATE TRIGGER IF NOT EXISTS trg_sources_touch AFTER UPDATE ON sources FOR EACH ROW
WHEN NEW.updated_at IS OLD.updated_at
BEGIN
    UPDATE sources SET updated_at = CURRENT_TIMESTAMP WHERE rowid = NEW.rowid;
END;
CREATE TRIGGER IF NOT EXISTS trg_destinations_touch AFTER UPDATE ON destinations FOR EACH ROW
WHEN NEW.updated_at IS OLD.updated_at
BEGIN
    UPDATE destinations SET updated_at = CURRENT_TIMESTAMP WHERE rowid = NEW.rowid;
END;
