-- ---------------------------------------------------------------- calculated views
DROP VIEW IF EXISTS kpi_monthly;
DROP VIEW IF EXISTS kpi_daily;
DROP VIEW IF EXISTS movement_calc;
CREATE VIEW movement_calc AS
SELECT t.*,
       j1.type AS source_type,
       j2.type AS dest_type
FROM movement t
LEFT JOIN sources j1 ON j1.source = t.source
LEFT JOIN destinations j2 ON j2.destination = t.destination;

-- ---------------------------------------------------------------- KPI views (workbook KPI catalogue)
-- Ex-pit = source type Pit; ore = material starting with Ore; rehandle = source type Stockpile.
-- Ratios are NULL when the denominator is zero. Sums are 0 on days without rows, as in the workbook.
CREATE VIEW kpi_daily AS
WITH days AS (
    SELECT date FROM movement UNION SELECT date FROM mining_daily UNION SELECT date FROM fleet UNION SELECT date FROM plant_daily UNION SELECT date FROM gold UNION SELECT date FROM safety_daily
),
agg_movement AS (
    SELECT date,
           SUM(CASE WHEN is_ore = 1 AND source_type = 'Pit' THEN CAST(tonnes_t AS REAL) ELSE 0 END) AS ore_mined_t,
           SUM(CASE WHEN source_type = 'Pit' THEN CAST(ore_oz AS REAL) ELSE 0 END) AS ore_mined_oz,
           SUM(CASE WHEN is_ore = 0 AND source_type = 'Pit' THEN CAST(tonnes_t AS REAL) ELSE 0 END) AS waste_t,
           SUM(CASE WHEN source_type = 'Stockpile' THEN CAST(tonnes_t AS REAL) ELSE 0 END) AS rehandle_t
    FROM movement_calc
    GROUP BY date
),
agg_mining_daily AS (
    SELECT date,
           SUM(CAST(drill_m AS REAL)) AS drill_m,
           SUM(CAST(blast_t AS REAL)) AS blast_t,
           SUM(CAST(explosives_kg AS REAL)) AS explosives_kg,
           SUM(CAST(diesel_l AS REAL)) AS diesel_mining_l,
           SUM(CAST(dewatering_m3 AS REAL)) AS dewatering_m3
    FROM mining_daily
    GROUP BY date
),
agg_fleet AS (
    SELECT date,
           SUM(CASE WHEN equipment_class = 'Excavator' THEN CAST(calendar_h AS REAL) ELSE 0 END) AS exc_calendar_h,
           SUM(CASE WHEN equipment_class = 'Excavator' THEN CAST(available_h AS REAL) ELSE 0 END) AS exc_available_h,
           SUM(CASE WHEN equipment_class = 'Excavator' THEN CAST(operating_h AS REAL) ELSE 0 END) AS exc_operating_h,
           SUM(CASE WHEN equipment_class = 'Haul Truck' THEN CAST(calendar_h AS REAL) ELSE 0 END) AS trk_calendar_h,
           SUM(CASE WHEN equipment_class = 'Haul Truck' THEN CAST(available_h AS REAL) ELSE 0 END) AS trk_available_h,
           SUM(CASE WHEN equipment_class = 'Haul Truck' THEN CAST(operating_h AS REAL) ELSE 0 END) AS trk_operating_h
    FROM fleet
    GROUP BY date
),
agg_plant AS (
    SELECT date,
           SUM(CAST(crushed_t AS REAL)) AS crushed_t,
           SUM(CAST(milled_t AS REAL)) AS milled_t,
           SUM(CAST(feed_oz AS REAL)) AS feed_oz,
           SUM(CAST(tails_oz AS REAL)) AS tails_oz,
           SUM(CAST(recovered_oz AS REAL)) AS recovered_oz,
           SUM(CAST(gravity_gold_oz AS REAL)) AS gravity_gold_oz,
           SUM(CAST(gold_poured_oz AS REAL)) AS gold_poured_oz,
           SUM(CAST(mill_run_h AS REAL)) AS mill_run_h,
           SUM(CAST(mill_planned_maint_h AS REAL)) AS mill_planned_maint_h,
           SUM(CAST(mill_unplanned_down_h AS REAL)) AS mill_unplanned_down_h,
           COUNT(mill_run_h) * 24 AS mill_calendar_h,
           SUM(CAST(crusher_run_h AS REAL)) AS crusher_run_h,
           SUM(CAST(cyanide_kg AS REAL)) AS cyanide_kg,
           SUM(CAST(lime_kg AS REAL)) AS lime_kg,
           SUM(CAST(grinding_media_kg AS REAL)) AS grinding_media_kg,
           SUM(CAST(power_kwh AS REAL)) AS power_kwh,
           SUM(CAST(raw_water_m3 AS REAL)) AS raw_water_m3,
           NULLIF(SUM(CAST(gic_oz AS REAL)), 0) AS gic_oz
    FROM plant_daily
    GROUP BY date
),
agg_gold AS (
    SELECT date,
           SUM(CASE WHEN type = 'Shipment' THEN CAST(gold_oz AS REAL) ELSE 0 END) AS gold_shipped_oz,
           SUM(CASE WHEN type = 'Sale' THEN CAST(gold_oz AS REAL) ELSE 0 END) AS gold_sold_oz,
           SUM(CASE WHEN type = 'Shipment' THEN CAST(dore_kg AS REAL) ELSE 0 END) AS dore_shipped_kg
    FROM gold
    GROUP BY date
),
agg_safety AS (
    SELECT date,
           SUM(CAST(hours_total AS REAL)) AS hours_worked,
           SUM(fatality) AS fatality,
           SUM(lti) AS lti,
           SUM(rwi) AS rwi,
           SUM(mti) AS mti,
           SUM(fai) AS fai,
           SUM(recordables) AS recordables,
           SUM(near_miss) AS near_miss,
           SUM(hazard_reports) AS hazard_reports,
           SUM(hpi) AS hpi,
           SUM(env_incidents) AS env_incidents,
           SUM(community_incidents) AS community_incidents,
           SUM(vehicle_incidents) AS vehicle_incidents,
           SUM(toolbox_talks) AS toolbox_talks,
           SUM(inspections) AS inspections
    FROM safety_daily
    GROUP BY date
),
base AS (
    SELECT d.date,
           COALESCE(a1.ore_mined_t, 0) AS ore_mined_t,
           COALESCE(a1.ore_mined_oz, 0) AS ore_mined_oz,
           COALESCE(a1.waste_t, 0) AS waste_t,
           COALESCE(a1.rehandle_t, 0) AS rehandle_t,
           COALESCE(a2.drill_m, 0) AS drill_m,
           COALESCE(a2.blast_t, 0) AS blast_t,
           COALESCE(a2.explosives_kg, 0) AS explosives_kg,
           COALESCE(a2.diesel_mining_l, 0) AS diesel_mining_l,
           COALESCE(a2.dewatering_m3, 0) AS dewatering_m3,
           COALESCE(a3.exc_calendar_h, 0) AS exc_calendar_h,
           COALESCE(a3.exc_available_h, 0) AS exc_available_h,
           COALESCE(a3.exc_operating_h, 0) AS exc_operating_h,
           COALESCE(a3.trk_calendar_h, 0) AS trk_calendar_h,
           COALESCE(a3.trk_available_h, 0) AS trk_available_h,
           COALESCE(a3.trk_operating_h, 0) AS trk_operating_h,
           COALESCE(a4.crushed_t, 0) AS crushed_t,
           COALESCE(a4.milled_t, 0) AS milled_t,
           COALESCE(a4.feed_oz, 0) AS feed_oz,
           COALESCE(a4.tails_oz, 0) AS tails_oz,
           COALESCE(a4.recovered_oz, 0) AS recovered_oz,
           COALESCE(a4.gravity_gold_oz, 0) AS gravity_gold_oz,
           COALESCE(a4.gold_poured_oz, 0) AS gold_poured_oz,
           COALESCE(a4.mill_run_h, 0) AS mill_run_h,
           COALESCE(a4.mill_planned_maint_h, 0) AS mill_planned_maint_h,
           COALESCE(a4.mill_unplanned_down_h, 0) AS mill_unplanned_down_h,
           COALESCE(a4.mill_calendar_h, 0) AS mill_calendar_h,
           COALESCE(a4.crusher_run_h, 0) AS crusher_run_h,
           COALESCE(a4.cyanide_kg, 0) AS cyanide_kg,
           COALESCE(a4.lime_kg, 0) AS lime_kg,
           COALESCE(a4.grinding_media_kg, 0) AS grinding_media_kg,
           COALESCE(a4.power_kwh, 0) AS power_kwh,
           COALESCE(a4.raw_water_m3, 0) AS raw_water_m3,
           a4.gic_oz AS gic_oz,
           COALESCE(a5.gold_shipped_oz, 0) AS gold_shipped_oz,
           COALESCE(a5.gold_sold_oz, 0) AS gold_sold_oz,
           COALESCE(a5.dore_shipped_kg, 0) AS dore_shipped_kg,
           COALESCE(a6.hours_worked, 0) AS hours_worked,
           COALESCE(a6.fatality, 0) AS fatality,
           COALESCE(a6.lti, 0) AS lti,
           COALESCE(a6.rwi, 0) AS rwi,
           COALESCE(a6.mti, 0) AS mti,
           COALESCE(a6.fai, 0) AS fai,
           COALESCE(a6.recordables, 0) AS recordables,
           COALESCE(a6.near_miss, 0) AS near_miss,
           COALESCE(a6.hazard_reports, 0) AS hazard_reports,
           COALESCE(a6.hpi, 0) AS hpi,
           COALESCE(a6.env_incidents, 0) AS env_incidents,
           COALESCE(a6.community_incidents, 0) AS community_incidents,
           COALESCE(a6.vehicle_incidents, 0) AS vehicle_incidents,
           COALESCE(a6.toolbox_talks, 0) AS toolbox_talks,
           COALESCE(a6.inspections, 0) AS inspections
    FROM days d
    LEFT JOIN agg_movement a1 ON a1.date = d.date
    LEFT JOIN agg_mining_daily a2 ON a2.date = d.date
    LEFT JOIN agg_fleet a3 ON a3.date = d.date
    LEFT JOIN agg_plant a4 ON a4.date = d.date
    LEFT JOIN agg_gold a5 ON a5.date = d.date
    LEFT JOIN agg_safety a6 ON a6.date = d.date
)
SELECT b.date,
       b.ore_mined_t,
       b.ore_mined_oz,
       CASE WHEN (b.ore_mined_t) > 0 THEN (b.ore_mined_oz*31.1035) / (b.ore_mined_t) END AS ore_grade_gpt,
       b.waste_t,
       b.ore_mined_t+b.waste_t AS tmm_t,
       CASE WHEN (b.ore_mined_t) > 0 THEN (b.waste_t) / (b.ore_mined_t) END AS strip_ratio,
       b.rehandle_t,
       b.drill_m,
       b.blast_t,
       b.explosives_kg,
       CASE WHEN (b.blast_t) > 0 THEN (b.explosives_kg) / (b.blast_t) END AS powder_factor_kgpt,
       b.diesel_mining_l,
       b.dewatering_m3,
       b.exc_calendar_h,
       b.exc_available_h,
       b.exc_operating_h,
       CASE WHEN (b.exc_calendar_h) > 0 THEN (b.exc_available_h) / (b.exc_calendar_h) END AS exc_availability_pct,
       CASE WHEN (b.exc_available_h) > 0 THEN (b.exc_operating_h) / (b.exc_available_h) END AS exc_utilisation_pct,
       b.trk_calendar_h,
       b.trk_available_h,
       b.trk_operating_h,
       CASE WHEN (b.trk_calendar_h) > 0 THEN (b.trk_available_h) / (b.trk_calendar_h) END AS trk_availability_pct,
       CASE WHEN (b.trk_available_h) > 0 THEN (b.trk_operating_h) / (b.trk_available_h) END AS trk_utilisation_pct,
       b.crushed_t,
       b.milled_t,
       b.feed_oz,
       b.tails_oz,
       b.recovered_oz,
       CASE WHEN (b.milled_t) > 0 THEN (b.feed_oz*31.1035) / (b.milled_t) END AS head_grade_gpt,
       CASE WHEN (b.milled_t) > 0 THEN (b.tails_oz*31.1035) / (b.milled_t) END AS tails_grade_gpt,
       CASE WHEN (b.feed_oz) > 0 THEN (b.recovered_oz) / (b.feed_oz) END AS recovery_pct,
       b.gravity_gold_oz,
       b.gold_poured_oz,
       b.mill_run_h,
       b.mill_planned_maint_h,
       b.mill_unplanned_down_h,
       b.mill_calendar_h,
       b.crusher_run_h,
       CASE WHEN (b.mill_run_h) > 0 THEN (b.milled_t) / (b.mill_run_h) END AS throughput_tph,
       CASE WHEN (b.mill_calendar_h) > 0 THEN (b.mill_calendar_h-b.mill_planned_maint_h-b.mill_unplanned_down_h) / (b.mill_calendar_h) END AS mill_availability_pct,
       CASE WHEN (b.mill_calendar_h-b.mill_planned_maint_h-b.mill_unplanned_down_h) > 0 THEN (b.mill_run_h) / (b.mill_calendar_h-b.mill_planned_maint_h-b.mill_unplanned_down_h) END AS mill_utilisation_pct,
       b.cyanide_kg,
       b.lime_kg,
       b.grinding_media_kg,
       b.power_kwh,
       b.raw_water_m3,
       CASE WHEN (b.milled_t) > 0 THEN (b.cyanide_kg) / (b.milled_t) END AS cyanide_kgpt,
       CASE WHEN (b.milled_t) > 0 THEN (b.lime_kg) / (b.milled_t) END AS lime_kgpt,
       CASE WHEN (b.milled_t) > 0 THEN (b.grinding_media_kg) / (b.milled_t) END AS media_kgpt,
       CASE WHEN (b.milled_t) > 0 THEN (b.power_kwh) / (b.milled_t) END AS power_kwhpt,
       CASE WHEN (b.milled_t) > 0 THEN (b.raw_water_m3) / (b.milled_t) END AS water_m3pt,
       b.gic_oz,
       b.gold_shipped_oz,
       b.gold_sold_oz,
       b.dore_shipped_kg,
       b.hours_worked,
       b.fatality,
       b.lti,
       b.rwi,
       b.mti,
       b.fai,
       b.recordables,
       b.near_miss,
       b.hazard_reports,
       b.hpi,
       b.env_incidents,
       b.community_incidents,
       b.vehicle_incidents,
       b.toolbox_talks,
       b.inspections,
       CASE WHEN ((SELECT COALESCE(SUM(CAST(s.hours_total AS REAL)), 0) FROM safety_daily s WHERE s.date >= date(b.date, 'start of month', '-12 months') AND s.date <= b.date) + (SELECT COALESCE(SUM(CAST(h.hours_total AS REAL)), 0) FROM safety_history h WHERE h.month >= date(b.date, 'start of month', '-12 months') AND h.month < date(b.date, 'start of month') AND NOT EXISTS (SELECT 1 FROM safety_daily s2 WHERE date(s2.date, 'start of month') = h.month))) > 0 THEN ((SELECT COALESCE(SUM(s.recordables), 0) FROM safety_daily s WHERE s.date >= date(b.date, 'start of month', '-12 months') AND s.date <= b.date) + (SELECT COALESCE(SUM(h.recordables), 0) FROM safety_history h WHERE h.month >= date(b.date, 'start of month', '-12 months') AND h.month < date(b.date, 'start of month') AND NOT EXISTS (SELECT 1 FROM safety_daily s2 WHERE date(s2.date, 'start of month') = h.month))) * 1000000 / ((SELECT COALESCE(SUM(CAST(s.hours_total AS REAL)), 0) FROM safety_daily s WHERE s.date >= date(b.date, 'start of month', '-12 months') AND s.date <= b.date) + (SELECT COALESCE(SUM(CAST(h.hours_total AS REAL)), 0) FROM safety_history h WHERE h.month >= date(b.date, 'start of month', '-12 months') AND h.month < date(b.date, 'start of month') AND NOT EXISTS (SELECT 1 FROM safety_daily s2 WHERE date(s2.date, 'start of month') = h.month))) END AS trifr_12m,
       CASE WHEN ((SELECT COALESCE(SUM(CAST(s.hours_total AS REAL)), 0) FROM safety_daily s WHERE s.date >= date(b.date, 'start of month', '-12 months') AND s.date <= b.date) + (SELECT COALESCE(SUM(CAST(h.hours_total AS REAL)), 0) FROM safety_history h WHERE h.month >= date(b.date, 'start of month', '-12 months') AND h.month < date(b.date, 'start of month') AND NOT EXISTS (SELECT 1 FROM safety_daily s2 WHERE date(s2.date, 'start of month') = h.month))) > 0 THEN ((SELECT COALESCE(SUM(s.lti), 0) FROM safety_daily s WHERE s.date >= date(b.date, 'start of month', '-12 months') AND s.date <= b.date) + (SELECT COALESCE(SUM(h.lti), 0) FROM safety_history h WHERE h.month >= date(b.date, 'start of month', '-12 months') AND h.month < date(b.date, 'start of month') AND NOT EXISTS (SELECT 1 FROM safety_daily s2 WHERE date(s2.date, 'start of month') = h.month))) * 1000000 / ((SELECT COALESCE(SUM(CAST(s.hours_total AS REAL)), 0) FROM safety_daily s WHERE s.date >= date(b.date, 'start of month', '-12 months') AND s.date <= b.date) + (SELECT COALESCE(SUM(CAST(h.hours_total AS REAL)), 0) FROM safety_history h WHERE h.month >= date(b.date, 'start of month', '-12 months') AND h.month < date(b.date, 'start of month') AND NOT EXISTS (SELECT 1 FROM safety_daily s2 WHERE date(s2.date, 'start of month') = h.month))) END AS ltifr_12m,
       CAST(julianday(b.date) - julianday((SELECT MAX(s.date) FROM safety_daily s WHERE s.lti > 0 AND s.date <= b.date)) AS INTEGER) AS days_since_lti
FROM base b;
CREATE VIEW kpi_monthly AS
SELECT date(k.date, 'start of month') AS month,
       COUNT(*) AS days_reported,
       SUM(k.ore_mined_t) AS ore_mined_t,
       SUM(k.ore_mined_oz) AS ore_mined_oz,
       CASE WHEN (SUM(k.ore_mined_t)) > 0 THEN (SUM(k.ore_mined_oz)*31.1035) / (SUM(k.ore_mined_t)) END AS ore_grade_gpt,
       SUM(k.waste_t) AS waste_t,
       SUM(k.tmm_t) AS tmm_t,
       CASE WHEN (SUM(k.ore_mined_t)) > 0 THEN (SUM(k.waste_t)) / (SUM(k.ore_mined_t)) END AS strip_ratio,
       SUM(k.rehandle_t) AS rehandle_t,
       SUM(k.drill_m) AS drill_m,
       SUM(k.blast_t) AS blast_t,
       SUM(k.explosives_kg) AS explosives_kg,
       CASE WHEN (SUM(k.blast_t)) > 0 THEN (SUM(k.explosives_kg)) / (SUM(k.blast_t)) END AS powder_factor_kgpt,
       SUM(k.diesel_mining_l) AS diesel_mining_l,
       SUM(k.dewatering_m3) AS dewatering_m3,
       SUM(k.exc_calendar_h) AS exc_calendar_h,
       SUM(k.exc_available_h) AS exc_available_h,
       SUM(k.exc_operating_h) AS exc_operating_h,
       CASE WHEN (SUM(k.exc_calendar_h)) > 0 THEN (SUM(k.exc_available_h)) / (SUM(k.exc_calendar_h)) END AS exc_availability_pct,
       CASE WHEN (SUM(k.exc_available_h)) > 0 THEN (SUM(k.exc_operating_h)) / (SUM(k.exc_available_h)) END AS exc_utilisation_pct,
       SUM(k.trk_calendar_h) AS trk_calendar_h,
       SUM(k.trk_available_h) AS trk_available_h,
       SUM(k.trk_operating_h) AS trk_operating_h,
       CASE WHEN (SUM(k.trk_calendar_h)) > 0 THEN (SUM(k.trk_available_h)) / (SUM(k.trk_calendar_h)) END AS trk_availability_pct,
       CASE WHEN (SUM(k.trk_available_h)) > 0 THEN (SUM(k.trk_operating_h)) / (SUM(k.trk_available_h)) END AS trk_utilisation_pct,
       SUM(k.crushed_t) AS crushed_t,
       SUM(k.milled_t) AS milled_t,
       SUM(k.feed_oz) AS feed_oz,
       SUM(k.tails_oz) AS tails_oz,
       SUM(k.recovered_oz) AS recovered_oz,
       CASE WHEN (SUM(k.milled_t)) > 0 THEN (SUM(k.feed_oz)*31.1035) / (SUM(k.milled_t)) END AS head_grade_gpt,
       CASE WHEN (SUM(k.milled_t)) > 0 THEN (SUM(k.tails_oz)*31.1035) / (SUM(k.milled_t)) END AS tails_grade_gpt,
       CASE WHEN (SUM(k.feed_oz)) > 0 THEN (SUM(k.recovered_oz)) / (SUM(k.feed_oz)) END AS recovery_pct,
       SUM(k.gravity_gold_oz) AS gravity_gold_oz,
       SUM(k.gold_poured_oz) AS gold_poured_oz,
       SUM(k.mill_run_h) AS mill_run_h,
       SUM(k.mill_planned_maint_h) AS mill_planned_maint_h,
       SUM(k.mill_unplanned_down_h) AS mill_unplanned_down_h,
       SUM(k.mill_calendar_h) AS mill_calendar_h,
       SUM(k.crusher_run_h) AS crusher_run_h,
       CASE WHEN (SUM(k.mill_run_h)) > 0 THEN (SUM(k.milled_t)) / (SUM(k.mill_run_h)) END AS throughput_tph,
       CASE WHEN (SUM(k.mill_calendar_h)) > 0 THEN (SUM(k.mill_calendar_h)-SUM(k.mill_planned_maint_h)-SUM(k.mill_unplanned_down_h)) / (SUM(k.mill_calendar_h)) END AS mill_availability_pct,
       CASE WHEN (SUM(k.mill_calendar_h)-SUM(k.mill_planned_maint_h)-SUM(k.mill_unplanned_down_h)) > 0 THEN (SUM(k.mill_run_h)) / (SUM(k.mill_calendar_h)-SUM(k.mill_planned_maint_h)-SUM(k.mill_unplanned_down_h)) END AS mill_utilisation_pct,
       SUM(k.cyanide_kg) AS cyanide_kg,
       SUM(k.lime_kg) AS lime_kg,
       SUM(k.grinding_media_kg) AS grinding_media_kg,
       SUM(k.power_kwh) AS power_kwh,
       SUM(k.raw_water_m3) AS raw_water_m3,
       CASE WHEN (SUM(k.milled_t)) > 0 THEN (SUM(k.cyanide_kg)) / (SUM(k.milled_t)) END AS cyanide_kgpt,
       CASE WHEN (SUM(k.milled_t)) > 0 THEN (SUM(k.lime_kg)) / (SUM(k.milled_t)) END AS lime_kgpt,
       CASE WHEN (SUM(k.milled_t)) > 0 THEN (SUM(k.grinding_media_kg)) / (SUM(k.milled_t)) END AS media_kgpt,
       CASE WHEN (SUM(k.milled_t)) > 0 THEN (SUM(k.power_kwh)) / (SUM(k.milled_t)) END AS power_kwhpt,
       CASE WHEN (SUM(k.milled_t)) > 0 THEN (SUM(k.raw_water_m3)) / (SUM(k.milled_t)) END AS water_m3pt,
       SUM(k.gold_shipped_oz) AS gold_shipped_oz,
       SUM(k.gold_sold_oz) AS gold_sold_oz,
       SUM(k.dore_shipped_kg) AS dore_shipped_kg,
       SUM(k.hours_worked) AS hours_worked,
       SUM(k.fatality) AS fatality,
       SUM(k.lti) AS lti,
       SUM(k.rwi) AS rwi,
       SUM(k.mti) AS mti,
       SUM(k.fai) AS fai,
       SUM(k.recordables) AS recordables,
       SUM(k.near_miss) AS near_miss,
       SUM(k.hazard_reports) AS hazard_reports,
       SUM(k.hpi) AS hpi,
       SUM(k.env_incidents) AS env_incidents,
       SUM(k.community_incidents) AS community_incidents,
       SUM(k.vehicle_incidents) AS vehicle_incidents,
       SUM(k.toolbox_talks) AS toolbox_talks,
       SUM(k.inspections) AS inspections
FROM kpi_daily k
GROUP BY date(k.date, 'start of month');

